CREATE TABLE t(id INTEGER PRIMARY KEY, g, i, r);
INSERT INTO t VALUES(0,NULL,0,1.7976931348623157e308),(1,NULL,256,0.5),(2,'c',2,9.99999999999999e22),(3,NULL,7,NULL),(4,'a',0,0.5),(5,'c',1000,5e-324),(6,'c',7,1e-10),(7,'c',9223372036854775807,-0.000123),(8,'c',4294967296,0.1),(9,'b',-1,1e-10),(10,'c',2,123456.789),(11,'a',-2147483648,1e100),(12,NULL,7,2.5),(13,'c',-9223372036854775807,9.99999999999999e22),(14,'b',10,1.5),(15,'c',10,0.7),(16,'a',-2147483648,1.5),(17,'b',-7,-0.5),(18,'b',9007199254740993,1.7976931348623157e308),(19,NULL,256,1.0000000000000002),(20,'b',NULL,0.5),(21,'b',-2147483648,1.7976931348623157e308),(22,'b',123456789012,123456.789);
SELECT g, count(*), count(i), sum(i), total(i), avg(i), min(i), max(i), sum(r), avg(r), group_concat(i) FROM t GROUP BY g ORDER BY g;
SELECT g, i, r, row_number() OVER (PARTITION BY g ORDER BY i, id), sum(r) OVER (ORDER BY id ROWS 3 PRECEDING), rank() OVER (ORDER BY i), lag(i) OVER (ORDER BY id), ntile(3) OVER (ORDER BY id) FROM t ORDER BY id;
SELECT * FROM t WHERE i > 5 OR r < 1.0 ORDER BY r, i, id LIMIT 20;
SELECT i, r, i + r, i * r, i / (r + 1) FROM t ORDER BY id;
